package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct { // 01 LEDGER-REC, 14 bytes
	BrBranch string // PIC X(2) @0 len=2
	BrAcct   string // PIC X(4) @2 len=4
	BrType   string // PIC X(1) @6 len=1
	BrAmt    decimal.Decimal // PIC 9(5)V99 @7 len=7
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"           // PIC X len=1 = "N"
var WsFirstFlag string = "Y"         // PIC X len=1 = "Y"
var WsPrevBranch string = "  "       // PIC X(2) len=2 = SPACES
var WsPrevAcct string = "    "       // PIC X(4) len=4 = SPACES
var WsBal decimal.Decimal = decimal.NewFromInt(0)       // PIC S9(7)V99 len=9 = 0
var WsBranchTot decimal.Decimal = decimal.NewFromInt(0) // PIC S9(9)V99 len=11 = 0
var WsGrandTot decimal.Decimal = decimal.NewFromInt(0)  // PIC S9(9)V99 len=11 = 0
var WsSkipped int64 = 0             // PIC 99 len=2 = 0
var WsAmtEd string                  // PIC ZZ,ZZ9.99 len=9
var WsBalEd string                  // PIC -Z,ZZZ,ZZ9.99 len=13
var WsTotEd string                  // PIC -ZZZ,ZZZ,ZZ9.99 len=15

var curRec LedgerRec

var ledgerLines []string
var ledgerIndex int

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func isFirstRecord() bool {
	return WsFirstFlag == "Y"
}

func parseAmt(s string) decimal.Decimal {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else {
			d = 0
		}
		n = n*10 + d
	}
	return decimal.New(n, -2)
}

func storeBal(v decimal.Decimal) decimal.Decimal {
	vt := v.Truncate(2)
	cents := vt.Shift(2).Truncate(0).IntPart()
	const mod int64 = 1000000000
	cents = cents % mod
	return decimal.New(cents, -2)
}

func storeBranchTot(v decimal.Decimal) decimal.Decimal {
	vt := v.Truncate(2)
	cents := vt.Shift(2).Truncate(0).IntPart()
	const mod int64 = 100000000000
	cents = cents % mod
	return decimal.New(cents, -2)
}

func storeGrandTot(v decimal.Decimal) decimal.Decimal {
	vt := v.Truncate(2)
	cents := vt.Shift(2).Truncate(0).IntPart()
	const mod int64 = 100000000000
	cents = cents % mod
	return decimal.New(cents, -2)
}

func formatAmtEd(v decimal.Decimal) string {
	vt := v.Truncate(2)
	if vt.Sign() < 0 {
		vt = vt.Neg()
	}
	cents := vt.Shift(2).Truncate(0).IntPart()
	if cents < 0 {
		cents = -cents
	}
	intPart := cents / 100
	frac := cents % 100
	const N = 5
	intMod := intPart % 100000
	digits := fmt.Sprintf("%05d", intMod)
	first := N
	for i := 0; i < N; i++ {
		if digits[i] != '0' {
			first = i
			break
		}
	}
	var sb strings.Builder
	for i := 0; i < N; i++ {
		if i == 2 {
			if first >= 2 {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte(',')
			}
		}
		var ch byte
		if i < first {
			if i == N-1 {
				ch = '0'
			} else {
				ch = ' '
			}
		} else {
			ch = digits[i]
		}
		sb.WriteByte(ch)
	}
	sb.WriteByte('.')
	sb.WriteString(fmt.Sprintf("%02d", frac))
	return sb.String()
}

func formatBalEd(v decimal.Decimal) string {
	vt := v.Truncate(2)
	neg := vt.Sign() < 0
	av := vt
	if neg {
		av = vt.Neg()
	}
	cents := av.Shift(2).Truncate(0).IntPart()
	if cents < 0 {
		cents = -cents
	}
	intPart := cents / 100
	frac := cents % 100
	const N = 7
	intMod := intPart % 10000000
	digits := fmt.Sprintf("%07d", intMod)
	first := N
	for i := 0; i < N; i++ {
		if digits[i] != '0' {
			first = i
			break
		}
	}
	var sb strings.Builder
	if neg {
		sb.WriteByte('-')
	} else {
		sb.WriteByte(' ')
	}
	for i := 0; i < N; i++ {
		if i == 1 || i == 4 {
			k := i
			if first >= k {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte(',')
			}
		}
		var ch byte
		if i < first {
			if i == N-1 {
				ch = '0'
			} else {
				ch = ' '
			}
		} else {
			ch = digits[i]
		}
		sb.WriteByte(ch)
	}
	sb.WriteByte('.')
	sb.WriteString(fmt.Sprintf("%02d", frac))
	return sb.String()
}

func formatTotEd(v decimal.Decimal) string {
	vt := v.Truncate(2)
	neg := vt.Sign() < 0
	av := vt
	if neg {
		av = vt.Neg()
	}
	cents := av.Shift(2).Truncate(0).IntPart()
	if cents < 0 {
		cents = -cents
	}
	intPart := cents / 100
	frac := cents % 100
	const N = 9
	intMod := intPart % 1000000000
	digits := fmt.Sprintf("%09d", intMod)
	first := N
	for i := 0; i < N; i++ {
		if digits[i] != '0' {
			first = i
			break
		}
	}
	var sb strings.Builder
	if neg {
		sb.WriteByte('-')
	} else {
		sb.WriteByte(' ')
	}
	for i := 0; i < N; i++ {
		if i == 3 || i == 6 {
			k := i
			if first >= k {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte(',')
			}
		}
		var ch byte
		if i < first {
			if i == N-1 {
				ch = '0'
			} else {
				ch = ' '
			}
		} else {
			ch = digits[i]
		}
		sb.WriteByte(ch)
	}
	sb.WriteByte('.')
	sb.WriteString(fmt.Sprintf("%02d", frac))
	return sb.String()
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 64*1024), 1024*1024)
	ledgerLines = nil
	for scanner.Scan() {
		ledgerLines = append(ledgerLines, scanner.Text())
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	ledgerIndex = 0
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if !isFirstRecord() {
		AcctBreakPara()
		BranchBreakPara()
	}
	GrandPara()
}

func ReadPara() {
	if ledgerIndex >= len(ledgerLines) {
		WsEofFlag = "Y"
		return
	}
	line := ledgerLines[ledgerIndex]
	ledgerIndex++
	if len(line) < 14 {
		line = line + strings.Repeat(" ", 14-len(line))
	} else if len(line) > 14 {
		line = line[:14]
	}
	curRec.BrBranch = line[0:2]
	curRec.BrAcct = line[2:6]
	curRec.BrType = line[6:7]
	curRec.BrAmt = parseAmt(line[7:14])
}

func ProcessPara() {
	if isFirstRecord() {
		WsPrevBranch = curRec.BrBranch
		WsPrevAcct = curRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if curRec.BrBranch != WsPrevBranch {
			AcctBreakPara()
			BranchBreakPara()
			WsPrevBranch = curRec.BrBranch
			WsPrevAcct = curRec.BrAcct
		} else {
			if curRec.BrAcct != WsPrevAcct {
				AcctBreakPara()
				WsPrevAcct = curRec.BrAcct
			}
		}
	}
	PostPara()
	ReadPara()
}

func PostPara() {
	WsAmtEd = formatAmtEd(curRec.BrAmt)
	switch curRec.BrType {
	case "D":
		WsBal = storeBal(WsBal.Add(curRec.BrAmt))
		fmt.Fprint(os.Stdout, curRec.BrAcct+" D "+WsAmtEd+"\n")
	case "C":
		WsBal = storeBal(WsBal.Sub(curRec.BrAmt))
		fmt.Fprint(os.Stdout, curRec.BrAcct+" C "+WsAmtEd+"\n")
	default:
		WsSkipped = (WsSkipped + 1) % 100
		fmt.Fprint(os.Stdout, curRec.BrAcct+" ? SKIPPED\n")
	}
}

func AcctBreakPara() {
	WsBalEd = formatBalEd(WsBal)
	fmt.Fprint(os.Stdout, "  ACCOUNT "+WsPrevAcct+" BALANCE:"+WsBalEd+"\n")
	WsBranchTot = storeBranchTot(WsBranchTot.Add(WsBal))
	WsBal = decimal.NewFromInt(0)
}

func BranchBreakPara() {
	WsTotEd = formatTotEd(WsBranchTot)
	fmt.Fprint(os.Stdout, " BRANCH "+WsPrevBranch+" TOTAL:"+WsTotEd+"\n")
	WsGrandTot = storeGrandTot(WsGrandTot.Add(WsBranchTot))
	WsBranchTot = decimal.NewFromInt(0)
}

func GrandPara() {
	WsTotEd = formatTotEd(WsGrandTot)
	fmt.Fprint(os.Stdout, "GRAND TOTAL:"+WsTotEd+"\n")
	sk := WsSkipped % 100
	if sk < 0 {
		sk += 100
	}
	fmt.Fprint(os.Stdout, "SKIPPED: "+fmt.Sprintf("%02d", sk)+"\n")
}

func main() {
	MainPara()
}
